      }
    },
    {
      "id": "https://www.baidu.com/s?wd=%E6%AF%94%E5%88%A9%E6%97%B6%E9%98%9F%E5%9C%BA%E4%B8%8A%E5%86%85%E8%AE%A7",
      "title": "比利时队场上内讧",
      "url": "https://www.baidu.com/s?wd=%E6%AF%94%E5%88%A9%E6%97%B6%E9%98%9F%E5%9C%BA%E4%B8%8A%E5%86%85%E8%AE%A7",
      "extra": {
        "hover": "7月2日，世界杯1/16决赛比利时对阵塞内加尔比赛中，比利时队在0:2落后的压力下爆发了场上内讧，特罗萨德与队长蒂莱曼斯在补水时间激烈争吵，但随后两人在比赛尾声戏剧性地完成连线破门，帮助球队3分钟内连进两球扳平比分拖入加时。"
      }
    }
  ]
}

